                if y==0 or x==0 or y==h-1 or x==w-1: edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if not (0<=yy<h and 0<=xx<w):
                        continue
                    if grid[yy][xx]==grid[0][0]:
                        if (yy,xx) not in seen: seen.add((yy,xx)); q.append((yy,xx))
